const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chiangMai = ee.Geometry.Point([98.9853, 18.7883]).buffer(10000); // 10 km buffer
  const march2024 = ['2024-03-01', '2024-04-01'];
  const may2024 = ['2024-05-01', '2024-06-01'];

  // Helper function to get AOD mean for a given date range
  async function getAODMean(dateRange, location) {
    // Try MODIS Terra first
    let coll = ee.ImageCollection('MODIS/006/MOD04_L2')
                  .filterDate(dateRange[0], dateRange[1])
                  .filterBounds(location)
                  .select('Optical_Depth_Land_And_Ocean'); // AOD at 550 nm

    let size = coll.size().getInfo();
    if (size === 0) {
      // Try MODIS Aqua as fallback
      coll = ee.ImageCollection('MODIS/006/MYD04_L2')
                .filterDate(dateRange[0], dateRange[1])
                .filterBounds(location)
                .select('Optical_Depth_Land_And_Ocean');
      size = coll.size().getInfo();
      if (size === 0) {
        return {count: 0, mean: null, pixels: 0};
      }
    }

    // Compute mean image and reduce region
    const meanImg = coll.mean();
    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: location,
      scale: 3000,
      maxPixels: 1e9
    });

    const meanVal = stats.get('Optical_Depth_Land_And_Ocean').getInfo();
    const pixelCount = stats.get('Optical_Depth_Land_And_Ocean_count').getInfo();

    return {count: size, mean: meanVal, pixels: pixelCount};
  }

  // 2. Get AOD for both months
  const marchAOD = await getAODMean(march2024, chiangMai);
  const mayAOD = await getAODMean(may2024, chiangMai);

  // Print concise evidence
  console.log(`March 2024: Images=${marchAOD.count}, AOD=${marchAOD.mean?.toFixed(3)??'null'}, Pixels=${marchAOD.pixels}`);
  console.log(`May 2024: Images=${mayAOD.count}, AOD=${mayAOD.mean?.toFixed(3)??'null'}, Pixels=${mayAOD.pixels}`);

  // 3. Check for data availability (C1)
  if (marchAOD.count === 0 || mayAOD.count === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Check for valid pixels (C2)
  if (marchAOD.pixels === 0 || mayAOD.pixels === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validate AOD values (C3)
  // AOD typically 0–1.5, allow up to 2 as reasonable
  if (marchAOD.mean === null || mayAOD.mean === null ||
      isNaN(marchAOD.mean) || isNaN(mayAOD.mean) ||
      marchAOD.mean < 0 || marchAOD.mean > 2 ||
      mayAOD.mean < 0 || mayAOD.mean > 2) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Compare and output final answer
  if (marchAOD.mean > mayAOD.mean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
